=== extension/manifest.json
{
  "manifest_version": 3,
  "name": "Video Fact Check",
  "version": "0.1.0",
  "description": "Finds checkable claims and signs of AI generation in TikTok videos as you watch.",
  "minimum_chrome_version": "111",
  "background": { "service_worker": "dist/background.js" },
  "content_scripts": [
    {
      "matches": ["https://www.tiktok.com/*"],
      "js": ["dist/page-hook.js"],
      "run_at": "document_start",
      "world": "MAIN"
    },
    {
      "matches": ["https://www.tiktok.com/*"],
      "js": ["dist/content.js"],
      "run_at": "document_start"
    }
  ],
  "host_permissions": [
    "https://*.tiktok.com/*",
    "https://*.tiktokcdn.com/*",
    "https://*.tiktokcdn-us.com/*"
  ]
}
=== src/messages.ts
// Messages passed between the extension's scripts.
import type { TikTokVideo } from "./tiktok.ts";

/** Tags messages from page-hook.ts so content.ts ignores anything else posted on the page. */
export const PAGE_HOOK_SOURCE = "video-fact-check:page-hook";

export interface PageHookMessage {
  source: typeof PAGE_HOOK_SOURCE;
  videos: TikTokVideo[];
}

export interface FetchCaptionRequest {
  type: "fetchCaption";
  url: string;
}

export type FetchCaptionResponse =
  { ok: true; text: string } | { ok: false; error: string };
=== src/page-hook.ts
// Runs inside the TikTok page itself (not the extension's isolated world) so it
// can see the video data TikTok's own code downloads. It never changes what
// TikTok receives: it reads a copy of each response and hands it to content.ts.
import { PAGE_HOOK_SOURCE, type PageHookMessage } from "./messages.ts";
import { extractVideos, isTikTokApiUrl } from "./tiktok.ts";

function forward(json: unknown): void {
  const videos = extractVideos(json);
  if (videos.length === 0) return;
  const message: PageHookMessage = { source: PAGE_HOOK_SOURCE, videos };
  window.postMessage(message, window.location.origin);
}

const originalFetch = window.fetch;
window.fetch = async (...args: Parameters<typeof fetch>) => {
  const response = await originalFetch.apply(window, args);
  if (isTikTokApiUrl(response.url)) {
    // Responses that aren't JSON have nothing for us, so a parse failure is ignored.
    response
      .clone()
      .json()
      .then(forward, () => {});
  }
  return response;
};

const originalOpen = XMLHttpRequest.prototype.open;
XMLHttpRequest.prototype.open = function (
  this: XMLHttpRequest,
  ...args: unknown[]
) {
  this.addEventListener("load", () => {
    if (isTikTokApiUrl(this.responseURL)) forward(readJson(this));
  });
  Reflect.apply(originalOpen, this, args);
} as typeof XMLHttpRequest.prototype.open;

function readJson(request: XMLHttpRequest): unknown {
  if (request.responseType === "json") return request.response;
  if (request.responseType !== "" && request.responseType !== "text") {
    return null;
  }
  try {
    return JSON.parse(request.responseText);
  } catch {
    return null;
  }
}
=== src/webvtt.ts
// Reads WebVTT, the caption file format TikTok serves.

export interface Cue {
  /** Seconds from the start of the video. */
  start: number;
  text: string;
}

const ENTITIES: Record<string, string> = {
  amp: "&",
  lt: "<",
  gt: ">",
  quot: '"',
  "#39": "'",
  nbsp: " ",
};

export function parseWebVtt(vtt: string): Cue[] {
  const cues: Cue[] = [];
  for (const block of vtt.replace(/\r\n?/g, "\n").split(/\n{2,}/)) {
    const lines = block.split("\n");
    const timingLine = lines.findIndex((line) => line.includes("-->"));
    // Blocks without a timing line are the header, NOTE, or STYLE blocks.
    if (timingLine === -1) continue;
    const text = lines
      .slice(timingLine + 1)
      .join(" ")
      .replace(/<[^>]*>/g, "")
      .replace(
        /&(amp|lt|gt|quot|#39|nbsp);/g,
        (_, name: string) => ENTITIES[name],
      )
      .replace(/\s+/g, " ")
      .trim();
    // Skip empty cues and repeats of the cue before (captions that linger).
    if (!text || text === cues.at(-1)?.text) continue;
    cues.push({ start: parseTimestamp(lines[timingLine]), text });
  }
  return cues;
}

function parseTimestamp(timingLine: string): number {
  const match = /(?:(\d+):)?(\d{1,2}):(\d{2})\.(\d{3})/.exec(timingLine);
  if (!match) return 0;
  const [, hours = "0", minutes, seconds, milliseconds] = match;
  return (
    Number(hours) * 3600 +
    Number(minutes) * 60 +
    Number(seconds) +
    Number(milliseconds) / 1000
  );
}
