content.content:
1	// Accuracy check, run before building the YouTube interface: finds the
2	// checkable claims in a saved transcript, checks each one with web search, and
3	// writes a report to grade by hand. Usage:
4	//   node --env-file=.env eval/check.ts eval/transcripts/<name>.txt [report.md]
5	// With an earlier report, checks that report's claims instead of finding new
6	// ones, so two models are compared on the same claims.
7	import Anthropic from "@anthropic-ai/sdk";
8	import { zodOutputFormat } from "@anthropic-ai/sdk/helpers/zod";
9	import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
10	import { basename } from "node:path";
11	import { z } from "zod";
12	import { MODEL, readClaims, reportSummary } from "./model.ts";
13	
14	// ponytail: a fixed cap keeps one run's cost predictable; raise it once the
15	// verdicts are known to be worth paying for.
16	const MAX_CLAIMS = 10;
17	// Twelve checks at once (three videos × four) made a third of the searches
18	// fail, and the model fell back on memory; two at a time, one video at a time.
19	const PARALLEL_CHECKS = 2;
20	const CHECK_TRIES = 3;
21	
22	const client = new Anthropic();
23	
24	const ClaimsSchema = z.object({
25	  claims: z.array(
26	    z.object({
27	      time: z.string(),
28	      quote: z.string(),
29	      claim: z.string(),
30	      kind: z.enum(["fact", "statistic", "forecast", "attributed"]),
31	    }),
32	  ),
33	});
34	type Claim = Pick<
35	  z.infer<typeof ClaimsSchema>["claims"][number],
36	  "time" | "quote" | "claim"
37	>;
38	
39	const VerdictSchema = z.object({
40	  verdict: z.enum(["supported", "contradicted", "misleading", "unverified"]),
41	  explanation: z.string(),
42	  sources: z.array(
43	    z.object({ url: z.string(), title: z.string(), says: z.string() }),
44	  ),
45	});
46	type Verdict = z.infer<typeof VerdictSchema>;
47	
48	const FIND_CLAIMS = `You find the checkable claims in a video transcript for a fact-checker.
49	
50	A claim counts if a source could support or contradict it today: facts, statistics, dates, and what experts forecast. Leave out opinions, jokes, figures of speech, rhetorical questions, the speaker's plans, and speculation no source could speak to. When someone is quoted, the claim is what they asserted as fact (for example "Collins says she voted against the bill"), not their opinion.
51	
52	Transcripts are often automatic captions: names may be misspelled and punctuation missing. Write each claim as one standalone sentence with names spelled correctly, so it can be searched without the video. "time" is the timestamp of the line it comes from, and "quote" is the shortest exact span of the transcript it comes from.
53	
54	Return at most ${MAX_CLAIMS} claims, choosing the ones a viewer would most want checked: specific, consequential, or surprising. Skip near-duplicates.`;
55	
56	const CHECK_CLAIM = `You check one claim from a video against sources found with web search.
57	
58	Verdicts:
59	- supported: reliable sources agree with the claim as stated. A rounded number, or one inside the range experts give, is supported; mention the precise figure in the explanation.
60	- contradicted: reliable sources say otherwise.
61	- misleading: partly true, but a viewer would come away believing something false. A missing qualifier, or a debate among experts the claim takes one mainstream side of, is not enough on its own.
62	- unverified: the sources found don't settle it. This is an honest answer, not a failure; prefer it over guessing.
63	
