  player: Player,
  track: CaptionTrack,
  videoId: string,
): Promise<string> {
  const loaded = () => captionAddresses.get(videoId);
  // With captions already on, the player asks by itself.
  if (player.getOption("captions", "track")?.languageCode)
    return waitFor(loaded, "the player didn't load captions");
  const hide = document.createElement("style");
  hide.textContent =
    ".ytp-caption-window-container { display: none !important; }";
  document.head.append(hide);
  try {
    player.loadModule("captions");
    player.setOption("captions", "track", {
      languageCode: track.languageCode,
      kind: track.kind,
    });
    return await waitFor(loaded, "the player didn't load captions");
  } finally {
    player.setOption("captions", "track", {});
    hide.remove();
  }
}

/** Resolves with `check`'s first truthy answer, polling for up to WAIT_MS. */
function waitFor<T>(
  check: () => T | null | undefined,
  failure: string,
): Promise<T> {
  const started = Date.now();
  return new Promise((resolve, reject) => {
    const poll = () => {
      const value = check();
      if (value) resolve(value);
      else if (Date.now() - started > WAIT_MS) reject(new Error(failure));
      else setTimeout(poll, 200);
    };
    poll();
  });
}

type Unsourced<T> = T extends unknown ? Omit<T, "source"> : never;

function post(message: Unsourced<PageHookMessage>): void {
  window.postMessage(
    { source: PAGE_HOOK_SOURCE, ...message },
    window.location.origin,
  );
}

window.addEventListener("message", (event) => {
  if (
    event.source === window &&
    event.data?.source === CONTENT_SOURCE &&
    event.data.type === "readCaptions"
  ) {
    void readCaptions();
  }
});
// YouTube changes videos without loading a new page, and says so with this event.
document.addEventListener("yt-navigate-finish", () => void readCaptions());
void readCaptions();

