6	#vfc-toggle {
7	  flex: none;
8	  align-self: center;
9	  height: 28px;
10	  margin-right: 8px;
11	  padding: 0 12px;
12	  border: 0;
13	  border-radius: 14px;
14	  background: rgba(255, 255, 255, 0.16);
15	  color: #fff;
