20	#vfc-toggle:hover, #vfc-toggle[aria-expanded="true"] { background: rgba(255, 255, 255, 0.3); }
21	#vfc-toggle[data-state="error"] { background: rgba(255, 78, 69, 0.45); }
22	#vfc-toggle:focus-visible { outline: 2px solid #fff; outline-offset: 2px; }
23	#vfc-list {
24	  --vfc-text: #0f0f0f;
25	  --vfc-muted: #606060;
26	  --vfc-surface: rgba(0, 0, 0, 0.05);
27	  --vfc-hover: rgba(0, 0, 0, 0.1);
28	  --vfc-accent: #065fd4;
29	  margin: 0 0 16px;
30	  padding: 8px 8px 4px;
31	  border-radius: 12px;
32	  background: var(--vfc-surface);
33	  color: var(--vfc-text);
34	  font: 400 14px/20px Roboto, Arial, sans-serif;
35	}
36	html[dark] #vfc-list {
37	  --vfc-text: #f1f1f1;
38	  --vfc-muted: #aaa;
39	  --vfc-surface: rgba(255, 255, 255, 0.1);
40	  --vfc-hover: rgba(255, 255, 255, 0.2);
41	  --vfc-accent: #3ea6ff;
42	}
43	#vfc-list header { display: flex; align-items: center; justify-content: space-between; padding-left: 8px; }
44	#vfc-list h2 { margin: 0; font: 700 16px/22px Roboto, Arial, sans-serif; }
45	#vfc-list .vfc-note { margin: 2px 8px 8px; color: var(--vfc-muted); font-size: 13px; line-height: 18px; }
46	#vfc-list ol { margin: 0; padding: 0; list-style: none; }
47	#vfc-list button { color: inherit; font: inherit; cursor: pointer; }
48	#vfc-list button:focus-visible { outline: 2px solid var(--vfc-accent); outline-offset: 1px; }
49	#vfc-list .vfc-close { width: 36px; height: 36px; border: 0; border-radius: 50%; background: none; font-size: 22px; line-height: 1; }
50	#vfc-list .vfc-claim { display: flex; gap: 12px; width: 100%; padding: 8px; border: 0; border-radius: 8px; background: none; text-align: left; }
51	#vfc-list .vfc-close:hover, #vfc-list .vfc-claim:hover { background: var(--vfc-hover); }
52	#vfc-list .vfc-time { flex: none; min-width: 40px; color: var(--vfc-accent); font-weight: 500; font-variant-numeric: tabular-nums; }
53	#vfc-list .vfc-retry { height: 36px; margin: 0 8px 8px; padding: 0 16px; border: 0; border-radius: 18px; background: var(--vfc-hover); font-weight: 500; }
