#vfc-toggle { flex: none; align-self: center; height: 28px; margin-right: 8px; padding: 0 12px; border: 0; border-radius: 14px; background: rgba(255, 255, 255, 0.16); color: #fff; font: 500 13px/28px Roboto, Arial, sans-serif; white-space: nowrap; cursor: pointer; }
#vfc-toggle:hover, #vfc-toggle[aria-expanded="true"] { background: rgba(255, 255, 255, 0.3); }
#vfc-toggle[data-state="error"] { background: rgba(255, 78, 69, 0.45); }
#vfc-toggle:focus-visible { outline: 2px solid #fff; outline-offset: 2px; }
#vfc-list { --vfc-text: #0f0f0f; --vfc-muted: #606060; --vfc-surface: rgba(0, 0, 0, 0.05); --vfc-hover: rgba(0, 0, 0, 0.1); --vfc-accent: #065fd4; margin: 0 0 16px; padding: 8px 8px 4px; border-radius: 12px; background: var(--vfc-surface); color: var(--vfc-text); font: 400 14px/20px Roboto, Arial, sans-serif; }
html[dark] #vfc-list { --vfc-text: #f1f1f1; --vfc-muted: #aaa; --vfc-surface: rgba(255, 255, 255, 0.1); --vfc-hover: rgba(255, 255, 255, 0.2); --vfc-accent: #3ea6ff; }
